INSERT INTO `tbl_servicios` VALUES (1,'Planes Adicionales','En SAMAP ofrecemos beneficios adicionales en Odontología, Sepelio y Alta Complejidad.','<p>1.&nbsp;<strong>Plan de Odontología:</strong> Para que siempre luzcas una sonrisa saludable, con acceso a una red de especialistas y tratamientos esenciales.</p><p>2.&nbsp;<strong>Plan de Sepelio:</strong> Porque acompañarte en cada etapa de la vida es nuestro compromiso, ofrecemos este respaldo cuando más lo necesitas.</p><p>3.&nbsp;<strong>Plan de Alta Complejidad:</strong> Brindamos acceso a una cobertura integral para enfrentar momentos de salud delicados, con la tranquilidad de contar con atención médica avanzada.</p><p>En SAMAP, más que un seguro, somos un respaldo para vos y los tuyos.</p>','beneficios-icono-1.png',''),(2,'Assist Card','¡Viaja seguro con SAMAP! Ya sea por negocios o vacaciones, viajar tranquilo es el primer paso para una experiencia inolvidable.','CONSULTE LAS CONDICIONES GENERALES DE LAS CLÁUSULAS CORRESPONDIENTES A LOS LÍMITES Y/O IMPORTES<br><br>- ASISTENCIA MÉDICA EN CASO DE ACCIDENTE<br>- ASISTENCIA MÉDICA EN CASO DE ENFERMEDAD NO PREEXISTENTE (INCLUIDO COVID-19)<br>-&nbsp;DOLENCIAS PREEXISTENTES Y DOLENCIAS CRONICAS<br>- PRIMERA ATENCION MEDICA POR DOLENCIAS PREEXISTENTES Y DOLENCIAS CRONICAS<br>-&nbsp;ATENCIÓN POR ESPECIALISTAS<br>-&nbsp;MEDICAMENTOS EN ASISTENCIAS AMBULATORIAS<br>-&nbsp;MEDICAMENTOS EN ASISTENCIAS CON HOSPITALIZACIÓN<br>-&nbsp;ODONTOLOGÍA DE URGENCIA<br>-&nbsp;PRÓTESIS Y ORTESIS&nbsp;<br>-&nbsp;PRÁCTICA DE DEPORTES<br>-&nbsp;ESTADO DE EMBARAZO<br>-&nbsp;TRASLADOS SANITARIOS<br>-&nbsp;REPATRIACIÓN SANITARIA<br>-&nbsp;ACOMPAÑAMIENTO DE MENORES Y MAYORES<br>-&nbsp;TRASLADO DE UN FAMILIAR<br>-&nbsp;ESTANCIA DE UN FAMILIAR<br>-&nbsp;DIFERENCIA DE TARIFA POR VIAJE DE REGRESO RETRASADO O ANTICIPADO<br>- GASTOS DE HOTEL POR REPOSO FORZOSO LUEGO DE UNA HOSPITALIZACION<br>-&nbsp;ASISTENCIA EN CASO DE ROBO O EXTRAVÍO DE DOCUMENTOS<br>-&nbsp;REGRESO ANTICIPADO POR SINIESTRO GRAVE EN EL DOMICILIO<br>-&nbsp;REPATRIACIÓN O TRASLADOS FUNERARIOS<br>-&nbsp;LOCALIZACIÓN DE EQUIPAJES<br>-&nbsp;ASISTENCIA LEGAL/ADELANTO EN CONCEPTO DE PRÉSTAMO<br>-&nbsp;ANTICIPO DE FONDOS PARA FIANZAS POR RESPONSABILIDAD EN UN ACCIDENTE<br>-&nbsp;ASISTENCIA LEGAL PARA REALIZAR RECLAMOS A RAÍZ DE ACCIDENTES<br>-&nbsp;VALIDEZ TERRITORIAL<br>-&nbsp;DÍAS CONSECUTIVOS POR VIAJE<br>-&nbsp;LIMITACIONES Y EXCLUSIONES ESPECIALES POR EDAD','beneficios-icono-2.png',''),(3,'Descuento en Farmacias','Con SAMAP tenés descuentos en las principales cadenas de farmacias del país.','<span style=\"font-weight: bold; text-decoration-line: underline;\">CATEDRAL\r\n</span><br><span style=\"font-weight: bold;\">Medicamentos del LABORATIORIO CATEDRAL:\r\n</span><br>30% de descuento contado\r\n<br>27% de descuento tarjeta débito\r\n<br>25% de descuento tarjeta crédito\r\n<br><br><span style=\"font-weight: bold;\">Medicamentos Nacionales\r\n<br></span>20% de descuento contado\r\n<br>17% de descuento tarjeta débito\r\n<br>15% de descuento tarjeta crédito\r\n<br><br><span style=\"font-weight: bold;\">Medicamentos Importados y preparados Magistrales:</span>\r\n<br>20% de descuento contado\r\n<br>17% de descuento tarjeta débito\r\n<br>15% de descuento tarjeta crédito\r\n<br><br><span style=\"font-weight: bold;\">Consumo, Varios, Perfumería y Hospitalarios\r\n</span><br>18% de descuento contado\r\n<br>15% de descuento tarjeta débito\r\n<br>13% de descuento tarjeta crédito\r\n<br><br><span style=\"font-weight: bold; text-decoration-line: underline;\">FARMATOTAL\r\n</span><br>Medicamentos Nacionales:30%\r\n<br>Medicamentos Importados:20%	<br>Medicamentos Controlados:19%	<br>Productos Hospitalarios: 20%\r\n<br>Productos varios: 15%	<br>Perfumería: 20%\r\n<br><br><span style=\"font-weight: bold;\">&nbsp;<span style=\"text-decoration-line: underline;\">PUNTO FARMA</span>\r\nPOR COMPRAS AL CONTADO (EFECTIVO, TARJETA DE DÉBITO)</span>\r\n<br>* Medicamentos Nacionales: 20% de descuento sobre el precio público, todos los días.<br>* Medicamentos Importados: 18% de descuento sobre el precio público, todos los días.\r\n<br>* Perfumería y Artículos Varios: 15% de descuento sobre el precio público, todos los días.\r\n<br><br><span style=\"font-weight: bold;\">POR COMPRAS CON TARJETA DE CRÉDITO</span>\r\n<br>* Medicamentos Nacionales, Importados, Perfumería y Artículos Varios: 15% de descuento sobre el precio público, todos los días.\r\n<br><br><span style=\"font-weight: bold;\"><span style=\"text-decoration-line: underline;\">VICENTE SCAVONE\r\n</span><br>Medicamentos Nacionales Lasca\r\n</span><br>Hasta 30% por compras al contado, en efectivo o tarjeta de débito.\r\n<br>Hasta 25% por compras con tarjeta de crédito.\r\n<br><br><span style=\"font-weight: bold;\">Medicamentos Nacionales\r\n</span><br>Hasta 23% por compras al contado, en efectivo o tarjeta de débito.\r\n<br>Hasta 18% por compras con tarjeta de crédito.\r\n<br><br><span style=\"font-weight: bold;\">Medicamentos Importados:\r\n</span><br>Hasta 15% por compras al contado, en efectivo o tarjeta de débito.\r\n<br>Hasta 10% por compras con tarjeta de crédito.\r\n<br><br><span style=\"font-weight: bold;\">Artículos de Perfumería: </span><br>Hasta 17% por compras al contado, en efectivo o tarjeta de débito.\r\n<br>Hasta 12% por compras con tarjeta de crédito.<br><br><span style=\"font-weight: bold;\">Materia Prima:</span>\r\n<br>Hasta 10% por compras al contado, en efectivo o tarjeta de débito.\r\n<br>Hasta 5% por compras con tarjeta de crédito.\r\n<br><br><span style=\"font-weight: bold;\">Instrumentales:\r\n</span><br>Hasta 15% por compras al contado, en efectivo o tarjeta de débito.\r\n<br>Hasta 10% por compras con tarjeta de crédito.\r\n<br><br><span style=\"font-weight: bold;\">Artículos Varios:</span> <br>Hasta 12% por compras al contado, en efectivo o tarjeta de débito.\r\n<br>Hasta 7% por compras con tarjeta de crédito.\r\n<br><br><span style=\"font-weight: bold;\">Artículos Higiene Personal:</span>\r\n<br>Hasta 12% por compras al contado, en efectivo o tarjeta de débito.\r\n<br>Hasta 7% por compras con tarjeta de crédito.\r\n<br><br><span style=\"font-weight: bold;\">Suplementos:\r\n<br></span>Hasta 10% por compras al contado, en efectivo o tarjeta de débito.\r\n<br>Hasta 5% por compras con tarjeta de crédito.\r\n<br><br><span style=\"font-weight: bold;\">Dermocosmética:</span> <br>Hasta 15% por compras al contado, en efectivo o tarjeta de débito.\r\n<br>Hasta 10% por compras con tarjeta de crédito.','beneficios-icono-3.png',''),(5,'Convenio con los mejores Centros de Diagnóstico','Con SAMAP podés realizar tus estudios en los mejores centros de diagnósticos del país.','<p>Sanatorio Adventista de Asunción<br><br>Meyer LAB<br><br>LABCENTRAL<br><br></p><p>Imagix Centro de Diagnóstico<br><br>INSTITUTO IRIBAS<br><br>MED VITAL<br><br></p><p>Instituto Radiológico CALVO</p><p><br>Clínica Radiología \"Carlos Iribas\"&nbsp;</p><p><br>Instituto Codas Thompson<br><br></p><p>IRM S.A.&nbsp;<br><br></p><p>Terapeutix</p><p><br><br><span style=\"font-weight: bold;\">ESTUDIOS CARDIOLÓGICOS PEDIÁTRICOS</span><br><br>Dra. María Gloria Escobar<br></p><p>Ayala Velazquez y Tte. Insaurralde</p><p>(021) 296 725</p><p><br>Dr. Oscar Amalio Benitez<br></p><p>Tte. Ruiz 975 c/ Gral. Santos</p><p>(021) 206 583</p><p><br>Dr. Renee Szwako<br></p><p>Herrera 1636 c/ Rca. Francesa</p><p>(021) 225 644 / (021) 211 506</p><p><br>Imagix Centro de Diagnóstico<br></p><p>Curupayty 651 c/ Azara</p><p>(021) 412 -2000</p><p><br></p><p>Instituto Codas Thompson<br></p><p>Mcal. López 2925</p><p>(021) 600 579 / (021) 600 624</p><p><br>Instituto Radiológico CALVO<br></p><p>Mcal. López 1037 c/ J.M. Frutos</p><p>(021) 206 368 / (021) 206 967</p><p><br><span style=\"font-weight: bold;\">ANATOMÍA PATOLÓGICA</span><br><br>Dra. Soon Ja Lee<br><br>Dr. Carmelo Caballero</p><p>Dr. Antonio Cubilla<br><br>Prof. Dr. Jose Bellasai<br><br>Dra. Elena Kasamatsu<br></p><p><br>Dr. Hugo Boggino Ramallo - Dra. Bernardita Stark<br><br>Dr. Fernando Llamosas&nbsp;<br><br>Dra. Ingrid Rodríguez<br><br><br></p><p><br><br><span style=\"font-weight: bold;\">ECOGRAFÍA</span><br><br>Sanatorio Adventista de Asunción<br></p><p><br>Dr. Rubén Rojas&nbsp;<br></p><p><br>Imagix Centro de Diagnóstico<br></p><p><br>MED VITAL<br></p><p><br>Clínica Radiología \"Carlos Iribas\"&nbsp;<br><br><br></p><p><span style=\"font-weight: bold;\">ESTUDIO DE OTORRINOLARINGOLOGÍA</span><br><br>Centro Auditivo<br></p><p><br>Nelly Martinez<br>OIR Paraguay<br><br><br></p><p><br>Clínica Paranaense de Rehabilitación (según plan)<br>Edif. Médico Profesional PISO 1 Bo San Roque<br>0973 51 27 8<br></p><p><br>Fisiocenter&nbsp;<br>Avda. Perú n.° 568 c/ Azara<br>021-220-749<br></p><p><br>CEMEFIR (según plan)<br>Av. Venezuela 1039, Asunción<br>0982 409252<br></p><p><br>RANDALL (según plan)<br>Av. España 649, Asunción<br>(021) 221 703<br><br>FISIOMED<br>Av. Tte. Rojas Silva Barrio Pablo Rojas<br>0991 202777<br><br><span style=\"font-weight: bold;\">PODOLOGÍA * (ARANCEL PREFERENCIAL)</span><br><br>Lic. Shirley Grillon<br><br><span style=\"font-weight: bold;\"><br><br></span></p><p><span style=\"font-weight: bold;\">PAPANICOLAU Y COLPOSCOPIA</span><br><br>Dra. Gladys Roscher<br>Sanatorio Adventista de Asunción<br>Pettirosi 380 c/ Pai Perez<br>219-6000 / 219-6100<br></p><p><br>Dr. Juan Carlos Ferreira<br>Sanatorio Adventista de Asunción<br>Pettirosi 380 c/ Pai Perez<br>219-6000 / 219-6100</p><p><br>Dra. Lorena Bogado<br>Sanatorio Adventista de Asunción<br>Pettirosi 380 c/ Pai Perez<br>219-6000 / 219-6100</p><p><br>Dr. Zenón González<br>Juan de Mena 171 c/ José Berges<br>222-113<br><br><br><br><br></p><p><br><br><br></p><p><br></p>','beneficios-icono-4.png',''),(6,'Amplia Red de Prestadores a Nivel Nacional','En SAMAP ofrecemos una amplia red de prestadores a nivel nacional.','<span style=\"font-weight: bold;\">Asunción y Gran Asunción:</span><br>Aregua<br>Capiatá<br>Fernando de la Mora<br>Lambaré<br>Limpio<br>Luque<br>Mariano Roque Alonso<br>Ñemby<br>San Lorenzo<br>Villeta<br><br>Alto Paraná<br>Caacupé<br>Caaguazú<br>Caazapa<br>Carapegua<br>Canindeyu<br>Ciudad del Este<br>Coronel Oviedo<br>Concepción<br>Encarnación<br>Filadelfia - Chaco Paraguayo<br>Hohenau<br>Loma Plata - Chaco Paraguayo<br>Paraguari<br>Pedro Juan Caballero<br>Pilar<br>Salto del Guairá<br>San Estanislao<br>San Ignacio Misiones<br>Villarrica<br>Yguazú<br><br><br><br><br><br>','beneficios-icono-5.png',''),(7,'Sanatorio Propio','SAMAP te ofrece la mejora atención en el Sanatorio Adventista.','Con la garantía y el prestigio de una Institución de Salud con más de 65 años de trayectoria.&nbsp;\r\n<span style=\"font-weight: bold;\">Sanatorio Adventista de Asunción.\r\n</span><br>\r\n\r\n¡Excelencia y Calidad al servicio de la vida!\r\n\r\n<br><br><span style=\"font-weight: bold;\">\r\n\r\n\r\nMISIÓN\r\n</span><br>Ser una institución de salud autosustentable, dedicada a la atención y promoción de la salud física, mental, social y espiritual de nuestros asegurados, pacientes y comunidad, siguiendo el ejemplo del Señor Jesús, el Médico de los médicos.\r\n\r\n\r\n<br><br><span style=\"font-weight: bold;\">\r\n\r\n\r\nVISIÓN\r\n</span><br>Ser una institución de salud con altos estándares de calidad en la prevención y tratamiento de la enfermedad, promoviendo la salud integral de nuestros asegurados pacientes y comunidad.\r\n\r\n\r\n<br><br><span style=\"font-weight: bold;\">TORRE DR. IRA E. BAILIE\r\n</span><br>Contamos con 20 nuevas habitaciones de internación general, de éstas 14 habitaciones simples y 6 habitaciones en suite. Uniendo amplitud y confort para la satisfacción de nuestros pacientes.\r\n\r\n\r\n<br><br><span style=\"font-weight: bold;\">\r\n\r\n\r\nUNIDAD DE TERAPIA INTENSIVA\r\n\r\n\r\n</span><br>\r\n\r\n\r\nNuestra Terapia intensiva es una unidad modelo, cuenta con 8 boxes de vidrio individuales, con presión negativa en su interior y filtros HEPA que evitan que los gérmenes salgan del interior de los boxes proporcionando seguridad a todos los internados y al personal. Contamos con monitoreo centralizado de cámaras y de parámetros hemodinámicos para mayor seguridad.\r\n\r\n\r\n<br><br>El monitoreo también es seguido de forma remota desde una app por el jefe de terapia intensiva las 24 hs. Cuenta con amplias y cómodas dependencias de enfermería y otros sectores que posibilitan prestar un servicio de excelencia.\r\n\r\n\r\n<br><br><span style=\"font-weight: bold;\">QUIRÓFANO</span><br>\r\nContamos con un moderno quirófano, cuya construcción siguió los más altos estándares europeos.\r\n<br><br>\r\nDisponemos de 3 salas de operaciones amplias y equipadas con tecnología de última generación para brindarle a los pacientes la mayor seguridad y comodidad.\r\n<br><br>Los principales aspectos a destacar son: el piso antiestática, la presión positiva, flujo laminar con filtros HEPA y puertas de cierre electrónico para evitar el ingreso de gérmenes al área estéril.\r\n<br><br>Además el área está dotado de instrumental sofisticado que posibilita la realización de cirugías de alta complejidad, una completa sala de recuperación y una cálida sala de recepción para recién nacidos.\r\n<br><br>Pensando en nuestros profesionales, equipamos una cómoda sala de estar que garantiza descanso y confort a la espera QUIRÓFANO del procedimiento quirúrgico.<br><br>\r\n\r\n<span style=\"font-weight: bold;\">ESTUDIOS CARDIOLÓGICOS</span><br>\r\n- Guardia de hemodinamia 24hs por día, 365 días al año.\r\n<br>- Ecocardio, Mapa, Holter, Ergometría, Electrocardiograma, Rehabilitación cardíaca, Control de marcapasos.\r\n<br>- Staff de cardiólogos de los más prestigiosos del país.\r\n<br>- Presupuestos competitivos.\r\n<br>- Agilidad y rapidez en la derivación de los pacientes.\r\n<br>- Contacto directo y asesoría cardiológica para derivación de pacientes a hemodinamia.\r\n<br>- Informe por medio de un ticket con un Código QR inmediata posterior a la realización del estudio/procedimiento.<br>','beneficios-icono-6.png','');
